const ImU32 TEXT=IM_COL32(201,208,216,255),MUTED=IM_COL32(132,143,155,255),CYAN=IM_COL32(102,186,208,255),SELECT=IM_COL32(43,72,88,255),GREEN=IM_COL32(120,185,132,255);
Document& D(){return documents[documentIndex];}Graph& G(){return D().model;}
ImU32 CategoryColor(Category c){const ImU32 colors[]={IM_COL32(218,106,128,255),IM_COL32(92,192,213,255),IM_COL32(219,166,100,255),IM_COL32(134,189,144,255),IM_COL32(117,159,229,255),IM_COL32(178,146,223,255),IM_COL32(212,188,109,255),IM_COL32(186,132,203,255)};return colors[(int)c];}
ImU32 WithAlpha(ImU32 c,int a){return (c&0x00ffffffu)|((ImU32)a<<24);}
ImU32 PinColor(PinType t){switch(t){case PinType::Exec:return IM_COL32(219,226,233,255);case PinType::Float:return IM_COL32(136,199,150,255);case PinType::Bool:return IM_COL32(222,110,121,255);case PinType::Vector:return IM_COL32(221,194,106,255);case PinType::Entity:return IM_COL32(113,168,233,255);case PinType::Material:return IM_COL32(179,146,225,255);case PinType::String:return IM_COL32(213,148,204,255);}return TEXT;}
Icon NodeIcon(NodeType type){switch(type){case NodeType::BeginPlay:return Icon::Play;case NodeType::Tick:return Icon::Refresh;case NodeType::KeyInput:return Icon::Monitor;case NodeType::Branch:return Icon::Blueprint;case NodeType::Delay:return Icon::Animation;case NodeType::Sequence:return Icon::List;case NodeType::FloatValue:case NodeType::Add:return Icon::Plus;case NodeType::BoolValue:case NodeType::Greater:return Icon::Check;case NodeType::VectorValue:return Icon::Move;case NodeType::Multiply:return Icon::Scale;case NodeType::Lerp:return Icon::Link;case NodeType::GetActor:return Icon::Cube;case NodeType::SetPosition:return Icon::Move;case NodeType::RotateActor:return Icon::Rotate;case NodeType::SetVisibility:return Icon::Eye;case NodeType::SetMaterial:case NodeType::MaterialValue:return Icon::Material;case NodeType::PrintString:case NodeType::StringValue:return Icon::List;case NodeType::PlaySound:return Icon::Volume;case NodeType::SpawnEffect:return Icon::Sun;case NodeType::GetVariable:return Icon::Pin;case NodeType::SetVariable:return Icon::Save;}return Icon::Blueprint;}
void Text(float x,float y,const std::string& text,ImU32 color=TEXT,float size=12){draw->AddText(font,size*scale,{x,y},color,text.c_str());}
void Center(Rect r,const std::string& text,ImU32 color=TEXT,float size=12){auto z=font->CalcTextSizeA(size*scale,10000,0,text.c_str());Text(r.x+(r.w-z.x)/2,r.y+(r.h-z.y)/2,text,color,size);}
void Box(Rect r,ImU32 color,float rounding=3,bool border=false){draw->AddRectFilled(r.Min(),r.Max(),color,rounding*scale);if(border)draw->AddRect(r.Min(),r.Max(),BORDER,rounding*scale);}
void Glyph(Icon icon,float x,float y,float size=13,ImU32 color=MUTED){DrawIcon(draw,icon,{x,y},size*scale,color);}
void Tooltip(const char* text){if(ImGui::IsItemHovered(ImGuiHoveredFlags_DelayShort))ImGui::SetTooltip("%s",text);}
bool Hit(const char* id,Rect r){ImGui::SetCursorScreenPos(r.Min());return ImGui::InvisibleButton(id,{std::max(1.f,r.w),std::max(1.f,r.h)});}
bool Button(const char* id,Rect r,const char* label,Icon icon,bool active=false,bool iconOnly=false){bool clicked=Hit(id,r);Box(r,active?SELECT:ImGui::IsItemHovered()?IM_COL32(48,58,66,255):RAISED,3,true);Glyph(icon,r.x+(iconOnly?(r.w/scale-13)/2:8)*scale,r.y+(r.h-13*scale)/2,13,active?CYAN:TEXT);if(!iconOnly)Text(r.x+28*scale,r.y+(r.h-12*scale)/2,label,TEXT,12);return clicked;}
bool Search(const char* id,Rect r,char* value,size_t length,const char* hint){ImGui::SetCursorScreenPos(r.Min());ImGui::SetNextItemWidth(r.w);ImGui::PushStyleVar(ImGuiStyleVar_FramePadding,{25*scale,5*scale});bool changed=ImGui::InputTextWithHint(id,hint,value,length);ImGui::PopStyleVar();Glyph(Icon::Search,r.x+8*scale,r.y+7*scale,11);return changed;}
bool Match(const std::string& title,const char* query){std::string a=title,b=query;for(auto& c:a)c=(char)std::tolower((unsigned char)c);for(auto& c:b)c=(char)std::tolower((unsigned char)c);return b.empty()||a.find(b)!=std::string::npos;}
void Notify(const std::string& text,Severity severity=Severity::Info,Id node=0){notice=text;noticeUntil=ImGui::GetTime()+3.0;messages.push_back({text,severity,node});if(messages.size()>200)messages.erase(messages.begin());scrollOutputToBottom=true;}
void Changed(){D().dirty=true;D().compiled=false;}
void CommitProperty(){if(propertyEditNode){if(G().EndEdit())Changed();propertyEditNode=0;propertyEditItem=0;}}
void SelectNode(Id id){CommitProperty();selection.clear();if(id&&G().FindNode(id))selection.insert(id);selectedLink=0;selectedGroup=-1;}
void CleanupSelection(){for(auto it=selection.begin();it!=selection.end();)if(!G().FindNode(*it))it=selection.erase(it);else++it;if(selectedLink&&!G().FindConnection(selectedLink))selectedLink=0;}
Id Primary(){return selection.empty()?0:*selection.begin();}
float NodeHeight(const Node& n){const auto& spec=GetSpec(n.type);return 81+std::max(spec.inputs.size(),spec.outputs.size())*25.f;}
Rect NodeRect(const Node& n){float z=D().zoom*scale;return {canvas.x+D().pan.x+n.x*z,canvas.y+D().pan.y+n.y*z,224*z,NodeHeight(n)*z};}
ImVec2 Screen(ImVec2 p){float z=D().zoom*scale;return {canvas.x+D().pan.x+p.x*z,canvas.y+D().pan.y+p.y*z};}
ImVec2 World(ImVec2 p){float z=D().zoom*scale;return {(p.x-canvas.x-D().pan.x)/z,(p.y-canvas.y-D().pan.y)/z};}
ImVec2 PinPosition(const Node& n,int index,bool output){auto r=NodeRect(n);float z=D().zoom*scale;return {output?r.x+r.w:r.x,r.y+(58+index*25.f)*z};}
Rect Bounds(bool selectedOnly=false){bool found=false;float minx=0,miny=0,maxx=0,maxy=0;for(const auto& n:G().Nodes()){if(selectedOnly&&!selection.count(n.id))continue;if(!found){minx=n.x;miny=n.y;maxx=n.x+224;maxy=n.y+NodeHeight(n);found=true;}else{minx=std::min(minx,n.x);miny=std::min(miny,n.y);maxx=std::max(maxx,n.x+224);maxy=std::max(maxy,n.y+NodeHeight(n));}}return found?Rect{minx-45,miny-45,maxx-minx+90,maxy-miny+90}:Rect{0,0,800,450};}
void Fit(bool selectedOnly=false){auto b=Bounds(selectedOnly);D().zoom=std::clamp(std::min(canvas.w/(b.w*scale),canvas.h/(b.h*scale))*.89f,.28f,1.25f);float z=D().zoom*scale;D().pan={canvas.w/2-(b.x+b.w/2)*z,canvas.h/2-(b.y+b.h/2)*z};}
void ZoomAt(float newZoom,ImVec2 anchor){auto world=World(anchor);D().zoom=std::clamp(newZoom,.28f,1.8f);float z=D().zoom*scale;D().pan={anchor.x-canvas.x-world.x*z,anchor.y-canvas.y-world.y*z};}
void DefaultGroups(){D().groups={{"INITIALISE ACTOR",10,12,545,230,Category::Scene},{"GAMEPLAY LOGIC",563,12,540,230,Category::Flow},{"DATA & PARAMETERS",10,273,540,390,Category::Math}};}
void SaveLayout(){std::ofstream out(std::filesystem::u8path(D().file+".layout"));out<<"ATELIER_GRAPH_LAYOUT 1\n"<<D().zoom<<' '<<D().pan.x<<' '<<D().pan.y<<'\n'<<D().groups.size()<<'\n';for(auto& g:D().groups)out<<std::quoted(g.title)<<' '<<g.x<<' '<<g.y<<' '<<g.w<<' '<<g.h<<' '<<(int)g.category<<'\n';}
void LoadLayout(){std::ifstream in(std::filesystem::u8path(D().file+".layout"));std::string magic;int version;float z,x,y;size_t count;if(!(in>>magic>>version>>z>>x>>y>>count)||magic!="ATELIER_GRAPH_LAYOUT"||version!=1||count>100)return;std::vector<Group> loaded;for(size_t i=0;i<count;++i){Group g;int cat;if(!(in>>std::quoted(g.title)>>g.x>>g.y>>g.w>>g.h>>cat)||cat<0||cat>7)return;g.category=(Category)cat;loaded.push_back(g);}D().zoom=std::clamp(z,.28f,1.8f);D().pan={x,y};D().groups=loaded;needFit=false;}
void Save(){CommitProperty();std::string error;if(G().Save(D().file,&error)){SaveLayout();D().dirty=false;Notify("Saved "+std::filesystem::u8path(D().file).filename().u8string());}else Notify(error,Severity::Error);}
void Load(){CommitProperty();std::string error;if(G().Load(D().file,&error)){selection.clear();selectedLink=0;selectedGroup=-1;Changed();D().dirty=false;needFit=true;LoadLayout();Notify("Graph loaded");}else Notify(error,Severity::Error);}
void Compile(){CommitProperty();auto diagnostics=G().Validate();int errors=0,warnings=0;for(auto& d:diagnostics){messages.push_back({d.message,d.severity,d.node});errors+=d.severity==Severity::Error;warnings+=d.severity==Severity::Warning;}D().compiled=errors==0;std::ostringstream text;text<<(errors?"Compile failed":"Compile successful")<<" · "<<G().Nodes().size()<<" nodes · "<<G().Connections().size()<<" links";if(warnings)text<<" · "<<warnings<<" warnings";Notify(text.str(),errors?Severity::Error:Severity::Info);bottomTab=errors?1:0;}
void Run(){CommitProperty();lastRun=G().RunDemo();runTime=ImGui::GetTime();traceIndex=-1;for(auto& line:lastRun.logs)messages.push_back({line,lastRun.success?Severity::Info:Severity::Error,0});Notify(lastRun.success?"Preview finished · execution trace is ready":"Preview stopped · see diagnostics",lastRun.success?Severity::Info:Severity::Error);bottomTab=0;}
void Copy(){CommitProperty();clipboardNodes.clear();clipboardLinks.clear();for(auto& n:G().Nodes())if(selection.count(n.id))clipboardNodes.push_back(n);for(auto& c:G().Connections())if(selection.count(c.fromNode)&&selection.count(c.toNode))clipboardLinks.push_back(c);Notify(std::to_string(clipboardNodes.size())+" nodes copied");}
void Paste(ImVec2 location){CommitProperty();if(clipboardNodes.empty())return;float minx=clipboardNodes.front().x,miny=clipboardNodes.front().y;for(auto& n:clipboardNodes){minx=std::min(minx,n.x);miny=std::min(miny,n.y);}G().BeginEdit();std::map<Id,Id> mapping;selection.clear();selectedLink=0;selectedGroup=-1;for(auto old:clipboardNodes){Id id=G().AddNode(old.type,location.x+old.x-minx,location.y+old.y-miny);Node* n=G().FindNode(id);if(!n){G().CancelEdit();selection.clear();Notify("Paste could not be completed",Severity::Error);return;}Id newId=n->id;*n=old;n->id=newId;n->x=location.x+old.x-minx;n->y=location.y+old.y-miny;mapping[old.id]=id;selection.insert(id);}for(auto& c:clipboardLinks)G().Connect(mapping[c.fromNode],c.fromPin,mapping[c.toNode],c.toPin);G().EndEdit();Changed();Notify("Pasted "+std::to_string(selection.size())+" nodes");}
void Duplicate(){if(selection.empty())return;auto oldMessages=messages.size();Copy();if(messages.size()>oldMessages)messages.pop_back();auto b=Bounds(true);Paste({b.x+85,b.y+85});}
void Delete(){CommitProperty();if(selectedGroup>=0&&selectedGroup<(int)D().groups.size()){D().groups.erase(D().groups.begin()+selectedGroup);selectedGroup=-1;Changed();return;}G().BeginEdit();if(selectedLink){G().Disconnect(selectedLink);selectedLink=0;}else{auto ids=selection;for(Id id:ids)G().RemoveNode(id);selection.clear();}bool changed=G().EndEdit();if(changed){Changed();Notify("Selection deleted");}}
void AddComment(){CommitProperty();auto b=Bounds(!selection.empty());D().groups.push_back({"NEW COMMENT",b.x,b.y-22,b.w,b.h+22,Category::Scene});selectedGroup=(int)D().groups.size()-1;selection.clear();selectedLink=0;Changed();}
Id Create(NodeType type,ImVec2 location){CommitProperty();Id id=G().AddNode(type,location.x,location.y);if(!id){Notify("Node could not be created",Severity::Error);return 0;}SelectNode(id);Changed();return id;}
void AutoArrange(){CommitProperty();std::vector<Id> flow,data;for(auto& n:G().Nodes()){const auto& spec=GetSpec(n.type);bool exec=false;for(auto p:spec.inputs)exec|=p.type==PinType::Exec;for(auto p:spec.outputs)exec|=p.type==PinType::Exec;(exec?flow:data).push_back(n.id);}G().BeginEdit();for(size_t i=0;i<flow.size();++i){auto* n=G().FindNode(flow[i]);n->x=40+(i%4)*285.f;n->y=40+(i/4)*230.f;}for(size_t i=0;i<data.size();++i){auto* n=G().FindNode(data[i]);n->x=40+(i%4)*285.f;n->y=40+((flow.size()+3)/4)*230.f+(i/4)*200.f;}G().EndEdit();D().groups.clear();Changed();needFit=true;Notify("Nodes arranged");}
void SwitchDocument(int index){if(index==documentIndex)return;CommitProperty();if(nodeDragging){G().EndEdit();nodeDragging=false;}groupDragging=false;boxSelecting=false;panDragging=false;documentIndex=index;selection.clear();selectedLink=0;selectedGroup=-1;linking=false;pendingConnection={};needFit=true;lastRun={};traceIndex=-1;}
