void PinGlyph(ImVec2 p,PinType type,bool filled,float z){ImU32 c=PinColor(type);if(type==PinType::Exec){ImVec2 a={p.x-4*z,p.y-5*z},b={p.x+5*z,p.y},d={p.x-4*z,p.y+5*z};if(filled)draw->AddTriangleFilled(a,b,d,c);else draw->AddTriangle(a,b,d,c,1.2f*scale);}else{draw->AddCircleFilled(p,5*z,BG,16);if(filled)draw->AddCircleFilled(p,3.5f*z,c,16);draw->AddCircle(p,5*z,c,16,1.3f*scale);}}
