ImVec2 Curve(ImVec2 a,ImVec2 b,float t){float distance=std::max(65*scale,std::abs(b.x-a.x)*.46f);ImVec2 c={a.x+distance,a.y},d={b.x-distance,b.y};float u=1-t;return {u*u*u*a.x+3*u*u*t*c.x+3*u*t*t*d.x+t*t*t*b.x,u*u*u*a.y+3*u*u*t*c.y+3*u*t*t*d.y+t*t*t*b.y};}
float SegmentDistance(ImVec2 p,ImVec2 a,ImVec2 b){float x=b.x-a.x,y=b.y-a.y,l=x*x+y*y;float t=l>0?std::clamp(((p.x-a.x)*x+(p.y-a.y)*y)/l,0.f,1.f):0;float dx=p.x-a.x-t*x,dy=p.y-a.y-t*y;return std::sqrt(dx*dx+dy*dy);}
