Id HoverNode(ImVec2 mouse){Id result=0;for(auto& n:G().Nodes())if(NodeRect(n).Contains(mouse)){result=n.id;if(selection.count(n.id))return result;}return result;}
Id HoverLink(ImVec2 mouse){Id result=0;float closest=7*scale;for(auto& link:G().Connections()){auto* a=G().FindNode(link.fromNode);auto* b=G().FindNode(link.toNode);if(!a||!b)continue;auto start=PinPosition(*a,link.fromPin,true),end=PinPosition(*b,link.toPin,false);auto prev=start;for(int i=1;i<=30;++i){auto next=Curve(start,end,i/30.f);float d=SegmentDistance(mouse,prev,next);if(d<closest){closest=d;result=link.id;}prev=next;}}return result;}
